/**
 * End-to-end contracts for query-local Frontier state carried by the packed subset kernels.
 *
 * <p>
 * State IDs deliberately depend on the complete ordered physical prefix. Two derivations of the same logical subset
 * therefore receive different IDs. If a losing candidate overwrites only the evidence column while the winner's parent
 * path remains selected, the next extension observes an immediate order/state mismatch.
 * </p>
 */
class PackedFrontierSubsetKernelContractTest {

	@Test
	void denseKernelRetainsTheWinningOrderedPrefixStateAcrossReplacementAndReset() {
		assertEquals(PackedJoinEnumerator.DENSE_SUBSETS, PackedJoinEnumerator.subsetKernelForFactorCount(4));
		TrackingCostModel model = new TrackingCostModel();

		PackedPlanningResult result = PackedCascadesPlanner.optimize(chain(4), OptimizationGoal.root(), model);

		assertNotNull(result.selectedPlan());
		TrackingSession session = model.onlySession();
		assertTrue(session.appendCalls > 0, "dense subset enumeration must cost physical prefix extensions");
		assertTrue(session.maximumPrefixLength >= 2,
				"dense enumeration must reuse a retained multi-factor prefix");
		assertTrue(session.competingOrderCount() > 0,
				"the fixture must exercise replacement between distinct physical orders of one logical subset");
		assertTrue(session.emptyContextResets >= 4,
				"reusing the cost context for isolated factors must reset its evidence state to zero");
	}

	@Test
	void denseKernelRetainsTheGloballyOptimalOrderedContinuationState() {
		assertEquals(PackedJoinEnumerator.DENSE_SUBSETS, PackedJoinEnumerator.subsetKernelForFactorCount(3));
		BellmanCounterexampleCostModel model = new BellmanCounterexampleCostModel();
		ExhaustivePlan exhaustive = model.exhaustiveConnectedOptimum();

		assertTrue(
				model.costOf(List.of(BellmanCounterexampleCostModel.A, BellmanCounterexampleCostModel.B)) < model
						.costOf(List.of(BellmanCounterexampleCostModel.B, BellmanCounterexampleCostModel.A)),
				"A,B must be the locally cheaper representative of logical subset {A,B}");
		assertEquals(
				new ExhaustivePlan(List.of(BellmanCounterexampleCostModel.B, BellmanCounterexampleCostModel.A,
						BellmanCounterexampleCostModel.C), 3.0d),
				exhaustive,
				"exhaustive connected-prefix costing must establish the deliberately non-greedy optimum");

		PackedPlanningResult result = PackedCascadesPlanner.optimize(chain(3), OptimizationGoal.root(), model);
		ExhaustivePlan selected = new ExhaustivePlan(statementPredicates(result.selectedPlan()), result.totalCost());

		assertEquals(exhaustive, selected,
				() -> "one state per logical subset pruned the continuation state needed by the exhaustive optimum: "
						+ result.selectedPlan());
	}

	@Test
	void denseAndSparseKernelsAssembleTheWinnerFromItsOriginalCostingEvents() {
		for (int factorCount : new int[] { 2, 4, 17 }) {
			int expectedKernel = factorCount <= 4
					? PackedJoinEnumerator.DENSE_SUBSETS
					: PackedJoinEnumerator.SPARSE_LONG_SUBSETS;
			assertEquals(expectedKernel, PackedJoinEnumerator.subsetKernelForFactorCount(factorCount));
			PackedQuery query = PackedQueryCodec.encodeForPlanning(chain(factorCount));
			int relationCount = query.relationCount();
			PackedMemo memo = new PackedMemo(query, query.symbolCount(), relationCount, relationCount, 4,
					relationCount, relationCount * 2);
			TrackingSession session = new TrackingSession(new PackedQueryView(query), false, () -> {
			});
			PackedIncumbentSearch baseline = PackedIncumbentSearch.forSession(query, memo,
					new PackedSearchBudget(Long.MAX_VALUE, Long.MAX_VALUE), false, session);
			baseline.build();
			session.resetCandidateInvocations();

			PackedJoinEnumerator enumerator = PackedJoinEnumerator.forSession(query, memo,
					baseline.selectedRowsByGroup(), new PackedSearchBudget(Long.MAX_VALUE, Long.MAX_VALUE), session);
			enumerator.optimize(query.rootRelId());

			assertEquals(1, session.maximumCandidateInvocationCount(),
					() -> factorCount + "-factor kernel recosted an exact ordered-prefix candidate during assembly: "
							+ session.duplicateCandidateInvocations());
		}
	}

	@Test
	void retainedBinaryWinnerPreservesOpaqueFactorChildren() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern step = new StatementPattern(Var.of("stepStart"),
				Var.of("pathPredicate", values.createIRI("urn:path")), Var.of("stepEnd"));
		ArbitraryLengthPath path = new ArbitraryLengthPath(StatementPattern.Scope.DEFAULT_CONTEXTS,
				Var.of("subject"), step, Var.of("object"), null, 1L);
		StatementPattern marker = new StatementPattern(Var.of("subject"),
				Var.of("markerPredicate", values.createIRI("urn:marker")), Var.of("marker"));

		PackedPlanningResult result = PackedCascadesPlanner.optimize(new Join(path, marker), OptimizationGoal.root(),
				new TrackingCostModel());

		assertNotNull(result.selectedPlan());
		assertTrue(result.selectedPlan().getBindingNames().containsAll(Set.of("subject", "object", "marker")),
				result.selectedPlan()::toString);
	}

	@Test
	void internedMultiwordKernelPropagatesStateThroughGrowthWithoutCrossQueryLeakage() {
		assertEquals(PackedJoinEnumerator.INTERNED_MULTIWORD_SUBSETS,
				PackedJoinEnumerator.subsetKernelForFactorCount(65));
		TrackingCostModel model = new TrackingCostModel();

		PackedPlanningResult result = PackedCascadesPlanner.optimize(chain(65), OptimizationGoal.root(), model);

		assertNotNull(result.selectedPlan());
		TrackingSession session = model.onlySession();
		assertTrue(session.appendCalls >= 64,
				"the multiword kernel must cost every addition after its initial factor");
		assertTrue(session.maximumPrefixLength >= 64,
				"the aligned state path must survive growth beyond one machine word");
		assertTrue(session.emptyContextResets >= 65,
				"every isolated factor must begin with state zero even after long-prefix contexts were reused");
	}

	@Test
	void rootJoinRefinementReceivesTheWinningCombinedState() {
		for (int factorCount : new int[] { 2, 3, 9, 65 }) {
			TrackingCostModel model = new TrackingCostModel(true);

			PackedPlanningResult result = PackedCascadesPlanner.optimize(
					chain(factorCount), OptimizationGoal.root(), model);

			assertNotNull(result.selectedPlan());
			assertTrue(model.onlySession().rootJoinRefinementCalls > 0,
					() -> factorCount
							+ "-factor root join must be refined with its combined and both child states");
		}
	}

	@Test
	void correlatedHypergraphOwnsCostingBeforeItsWrittenJoinSpine() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		Filter source = new Filter(chain(4), new Compare(Var.of("v4"),
				new ValueConstant(values.createLiteral(0)), Compare.CompareOp.GT));
		TopologyOrderCostModel model = new TopologyOrderCostModel();

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(), model);

		assertNotNull(result.selectedPlan());
		TopologyOrderSession session = model.onlySession();
		assertTrue(session.firstContextualTransitionOrdinal > 0,
				"the correlated DPhyp lattice must cost at least one physical transition");
		assertTrue(session.firstCoveredSpineOrdinal == 0
				|| session.firstContextualTransitionOrdinal < session.firstCoveredSpineOrdinal,
				() -> "the written context-free spine was costed before its owning DPhyp lattice: transition="
						+ session.firstContextualTransitionOrdinal + ", spine=" + session.firstCoveredSpineOrdinal);
	}

	@Test
	void detachedRecipesAndStoreWideCacheRemainFreeOfQueryLocalState() {
		assertNoQueryLocalState(PackedPlanRecipe.class);
		assertNoQueryLocalState(PackedPlanCache.class);
		assertNoQueryLocalState(PackedPlanCache.Context.class);
		assertNoQueryLocalState(PackedPlanCache.PlanEntry.class);
		assertNoQueryLocalState(PackedPlanCache.QueryEntry.class);
	}

	private static TupleExpr chain(int factorCount) {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		TupleExpr result = factor(values, 0);
		for (int ordinal = 1; ordinal < factorCount; ordinal++) {
			result = new Join(result, factor(values, ordinal));
		}
		return result;
	}

	private static StatementPattern factor(SimpleValueFactory values, int ordinal) {
		return new StatementPattern(Var.of("v" + ordinal),
				Var.of("predicate" + ordinal, values.createIRI("urn:frontier-factor:" + ordinal)),
				Var.of("v" + (ordinal + 1)));
	}

	private static List<String> statementPredicates(TupleExpr expression) {
		List<String> predicates = new ArrayList<>();
		collectStatementPredicates(expression, predicates);
		return List.copyOf(predicates);
	}

	private static void collectStatementPredicates(TupleExpr expression, List<String> predicates) {
		if (expression instanceof Join join) {
			collectStatementPredicates(join.getLeftArg(), predicates);
			collectStatementPredicates(join.getRightArg(), predicates);
		} else if (expression instanceof StatementPattern pattern) {
			predicates.add(pattern.getPredicateVar().getValue().stringValue());
		}
	}

	private static void assertNoQueryLocalState(Class<?> owner) {
		for (Field field : owner.getDeclaredFields()) {
			String normalizedName = field.getName().replace("_", "").toLowerCase();
			String typeName = field.getType().getSimpleName();
			assertFalse(normalizedName.contains("evidencestate"),
					() -> owner.getSimpleName() + "." + field.getName() + " leaks a query-local state ID");
			assertFalse(typeName.equals("PackedCostSession")
					|| typeName.equals("EvidenceStateRef")
					|| typeName.equals("FrontierStateArena"),
					() -> owner.getSimpleName() + "." + field.getName() + " leaks " + typeName);
		}
	}

	private static final class TrackingCostModel implements PackedCostModel {

		private final List<TrackingSession> sessions = new ArrayList<>();
		private final boolean requireRootState;
		private int closeCount;

		private TrackingCostModel() {
			this(false);
		}

		private TrackingCostModel(boolean requireRootState) {
			this.requireRootState = requireRootState;
		}

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 1.0d : Double.NaN;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			TrackingSession session = new TrackingSession(query, requireRootState, () -> closeCount++);
			sessions.add(session);
			return session;
		}

		private TrackingSession onlySession() {
			assertEquals(1, sessions.size(), "one cold planning call must own exactly one estimator session");
			assertEquals(1, closeCount, "the packed planner must close the query-local state arena");
			return sessions.get(0);
		}
	}

	private static final class TopologyOrderCostModel implements PackedCostModel {

		private TopologyOrderSession session;
		private int closeCount;

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 1.0d : Double.NaN;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			session = new TopologyOrderSession(query, () -> closeCount++);
			return session;
		}

		private TopologyOrderSession onlySession() {
			assertNotNull(session);
			assertEquals(1, closeCount);
			return session;
		}
	}

	private static final class TopologyOrderSession implements PackedCostSession {

		private final PackedQueryView query;
		private final Runnable closeAction;
		private int nextStateId = 1;
		private int invocationOrdinal;
		private int firstContextualTransitionOrdinal;
		private int firstCoveredSpineOrdinal;

		private TopologyOrderSession(PackedQueryView query, Runnable closeAction) {
			this.query = query;
			this.closeAction = closeAction;
		}

		@Override
		public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
			invocationOrdinal++;
			if (query.isStatementPattern(relationId)) {
				output.setRows(1.0d, 1.0d);
				output.setEvidenceStateId(nextStateId++);
			}
		}

		@Override
		public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
			invocationOrdinal++;
			if (firstContextualTransitionOrdinal == 0) {
				firstContextualTransitionOrdinal = invocationOrdinal;
			}
			output.setContextualRows(1.0d, 1.0d);
			output.setEvidenceStateId(nextStateId++);
		}

		@Override
		public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
			invocationOrdinal++;
			if ((query.operatorTag(relationId) == PackedRelOp.JOIN || query.isFilter(relationId))
					&& context.prefixRelationCount() == 0 && firstCoveredSpineOrdinal == 0) {
				firstCoveredSpineOrdinal = invocationOrdinal;
			}
			if (output.evidenceStateId() == 0) {
				output.setEvidenceStateId(nextStateId++);
			}
		}

		@Override
		public void close() {
			closeAction.run();
		}
	}

	private static final class BellmanCounterexampleCostModel implements PackedCostModel {

		private static final String A = "urn:frontier-factor:0";
		private static final String B = "urn:frontier-factor:1";
		private static final String C = "urn:frontier-factor:2";
		private static final double JOIN_OUTPUT_ROWS = 1.0d;
		private static final double EXPENSIVE_CONTINUATION_WORK = 100.0d;
		private static final List<List<String>> CONNECTED_ORDERS = List.of(
				List.of(A, B, C),
				List.of(B, A, C),
				List.of(B, C, A),
				List.of(C, B, A));

		@Override
		public double estimateRows(PackedQueryView query, int relationId) {
			return query.isStatementPattern(relationId) ? 1_000.0d : Double.NaN;
		}

		@Override
		public PackedCostSession openSession(PackedQueryView query) {
			return new BellmanCounterexampleSession(query);
		}

		private ExhaustivePlan exhaustiveConnectedOptimum() {
			ExhaustivePlan optimum = null;
			for (List<String> order : CONNECTED_ORDERS) {
				ExhaustivePlan candidate = new ExhaustivePlan(order, costOf(order));
				if (optimum == null || candidate.cost() < optimum.cost()) {
					optimum = candidate;
				}
			}
			return optimum;
		}

		private double costOf(List<String> order) {
			double cost = 0.0d;
			for (int ordinal = 1; ordinal < order.size(); ordinal++) {
				cost += transitionWork(order.subList(0, ordinal), order.get(ordinal)) + JOIN_OUTPUT_ROWS;
			}
			return cost;
		}

		private static double transitionWork(List<String> prefix, String candidate) {
			if (prefix.equals(List.of(A)) && B.equals(candidate)) {
				return 0.0d;
			}
			if (prefix.equals(List.of(B)) && A.equals(candidate)) {
				return 1.0d;
			}
			if (prefix.equals(List.of(B, A)) && C.equals(candidate)) {
				return 0.0d;
			}
			return EXPENSIVE_CONTINUATION_WORK;
		}
	}

	private static final class BellmanCounterexampleSession implements PackedCostSession {

		private final PackedQueryView query;
		private final Map<List<Integer>, Integer> stateByOrderedPrefix = new HashMap<>();
		private int nextStateId = 1;

		private BellmanCounterexampleSession(PackedQueryView query) {
			this.query = query;
		}

		@Override
		public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
			if (!query.isStatementPattern(relationId)) {
				return;
			}
			output.setRows(1_000.0d, 0.0d);
			output.setEvidenceStateId(stateFor(List.of(relationId)));
		}

		@Override
		public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
			List<Integer> prefix = orderedPrefix(context);
			assertEquals(stateFor(prefix), context.evidenceStateId(),
					"continuation evidence must identify the exact ordered prefix being extended");
			List<String> prefixPredicates = prefix.stream().map(this::predicate).toList();
			output.setContextualRows(1.0d,
					BellmanCounterexampleCostModel.transitionWork(prefixPredicates, predicate(relationId)));

			List<Integer> combined = new ArrayList<>(prefix.size() + 1);
			combined.addAll(prefix);
			combined.add(relationId);
			output.setEvidenceStateId(stateFor(combined));
		}

		@Override
		public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
		}

		private List<Integer> orderedPrefix(PackedCostContext context) {
			List<Integer> prefix = new ArrayList<>(context.prefixRelationCount());
			for (int ordinal = 0; ordinal < context.prefixRelationCount(); ordinal++) {
				prefix.add(context.prefixRelationId(ordinal));
			}
			return List.copyOf(prefix);
		}

		private String predicate(int relationId) {
			return query.statementPatternValue(relationId, 1).stringValue();
		}

		private int stateFor(List<Integer> orderedPrefix) {
			return stateByOrderedPrefix.computeIfAbsent(List.copyOf(orderedPrefix), ignored -> nextStateId++);
		}
	}

	private record ExhaustivePlan(List<String> order, double cost) {
	}

	private static final class TrackingSession implements PackedCostSession {

		private final PackedQueryView query;
		private final boolean requireRootState;
		private final Runnable closeAction;
		private final Map<List<Integer>, Integer> stateByOrderedPrefix = new HashMap<>();
		private final Map<List<Integer>, Set<List<Integer>>> ordersByLogicalSubset = new HashMap<>();
		private final Map<List<Integer>, Integer> candidateInvocations = new HashMap<>();
		private int nextStateId = 1;
		private int appendCalls;
		private int maximumPrefixLength;
		private int emptyContextResets;
		private int rootJoinRefinementCalls;

		private TrackingSession(PackedQueryView query, boolean requireRootState, Runnable closeAction) {
			this.query = query;
			this.requireRootState = requireRootState;
			this.closeAction = closeAction;
		}

		@Override
		public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
			assertEquals(0, context.prefixRelationCount(),
					"an isolated factor must not inherit a prior candidate's prefix");
			assertEquals(0, context.evidenceStateId(),
					"an isolated factor must not inherit a prior candidate's evidence state");
			assertEquals(0, output.evidenceStateId(),
					"the reusable estimate slot must be cleared before isolated estimation");
			emptyContextResets++;
			if (!query.isStatementPattern(relationId)) {
				return;
			}
			output.setRows(1.0d, 1.0d);
			output.setEvidenceStateId(stateFor(List.of(relationId)));
		}

		@Override
		public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
			assertTrue(context.prefixRelationCount() > 0, "an append requires a nonempty physical prefix");
			assertEquals(0, output.evidenceStateId(),
					"the reusable estimate slot must be cleared before each competing append");
			List<Integer> prefix = orderedPrefix(context);
			int expectedStateId = stateFor(prefix);
			assertEquals(expectedStateId, context.evidenceStateId(),
					() -> "prefix " + prefix + " retained state " + context.evidenceStateId()
							+ " instead of its aligned winner state " + expectedStateId);

			List<Integer> combined = new ArrayList<>(prefix.size() + 1);
			combined.addAll(prefix);
			combined.add(relationId);
			candidateInvocations.merge(List.copyOf(combined), 1, Integer::sum);
			recordPhysicalOrder(combined);
			appendCalls++;
			maximumPrefixLength = Math.max(maximumPrefixLength, prefix.size());
			output.setContextualRows(1.0d, 1.0d + relationId);
			output.setEvidenceStateId(stateFor(combined));
		}

		@Override
		public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
			if (query.operatorTag(relationId) != PackedRelOp.JOIN && output.evidenceStateId() == 0) {
				output.setEvidenceStateId(stateFor(List.of(relationId)));
			}
			if (query.operatorTag(relationId) == PackedRelOp.JOIN && context.prefixRelationCount() > 0) {
				rootJoinRefinementCalls++;
				if (requireRootState) {
					assertTrue(context.evidenceStateId() > 0,
							"root refinement must receive the state produced by the complete raw join");
					assertEquals(context.evidenceStateId(), output.evidenceStateId(),
							"neutral root refinement must begin with the winning state already installed");
					assertTrue(context.leftInputEvidenceStateId() > 0,
							"root refinement must receive the winning prefix state");
					assertTrue(context.rightInputEvidenceStateId() > 0,
							"root refinement must receive the appended child state");
				}
			}
		}

		@Override
		public void close() {
			closeAction.run();
		}

		private List<Integer> orderedPrefix(PackedCostContext context) {
			List<Integer> prefix = new ArrayList<>(context.prefixRelationCount());
			for (int ordinal = 0; ordinal < context.prefixRelationCount(); ordinal++) {
				prefix.add(context.prefixRelationId(ordinal));
			}
			return List.copyOf(prefix);
		}

		private int stateFor(List<Integer> orderedPrefix) {
			return stateByOrderedPrefix.computeIfAbsent(List.copyOf(orderedPrefix), ignored -> nextStateId++);
		}

		private void recordPhysicalOrder(List<Integer> orderedPrefix) {
			List<Integer> immutableOrder = List.copyOf(orderedPrefix);
			Integer[] sorted = immutableOrder.toArray(Integer[]::new);
			Arrays.sort(sorted);
			List<Integer> logicalSubset = List.of(sorted);
			ordersByLogicalSubset.computeIfAbsent(logicalSubset, ignored -> new HashSet<>()).add(immutableOrder);
		}

		private long competingOrderCount() {
			return ordersByLogicalSubset.values().stream().filter(orders -> orders.size() > 1).count();
		}

		private void resetCandidateInvocations() {
			candidateInvocations.clear();
		}

		private int maximumCandidateInvocationCount() {
			return candidateInvocations.values().stream().mapToInt(Integer::intValue).max().orElse(0);
		}

		private Map<List<Integer>, Integer> duplicateCandidateInvocations() {
			Map<List<Integer>, Integer> duplicates = new HashMap<>();
			candidateInvocations.forEach((candidate, calls) -> {
				if (calls > 1) {
					duplicates.put(candidate, calls);
				}
			});
			return duplicates;
		}
	}
}
